{"language":"js","summary":"Discovery: repo layout, languages, git state, notepad setup","code":"const sh = async (c)=> (await Bun.$`sh -c ${c}`.nothrow().text());
const RUN_TMP = (await sh('mktemp -d')).trim();
const NOTE = (await sh('mktemp -t ulw-$(date +%Y%m%d-%H%M%S).XXXXXX.md')).trim();
globalThis.RUN_TMP=RUN_TMP; globalThis.NOTE=NOTE;
const r = await parallel([
 ()=>sh('pwd; git rev-parse --show-toplevel; git status --short | head; git log --oneline -5'),
 ()=>sh('git ls-files | wc -l; git ls-files | sed -E "s/.*\\.//" | sort | uniq -c | sort -rn | head -15'),
 ()=>sh('git ls-files | awk -F/ "{print \\$1}" | sort | uniq -c | sort -rn | head -30'),
 ()=>sh('ls -la; cat AGENTS.md 2>/dev/null | head -40'),
]);
print(RUN_TMP, NOTE); r.forEach(x=>print(x,'\n---'));"}

